'use strict';
// Independent regression against frozen CSVs generated by the supplied Python pipeline.
const fs=require('node:fs'),crypto=require('node:crypto'),path=require('node:path'),assert=require('node:assert/strict'),C=require('./core');
const [root,mapFile,output]=process.argv.slice(2),bytes=fs.readFileSync(path.join(root,'Source_data/proteinGroups_030822.txt'));
const data=C.parseMaxQuant(bytes.toString(),JSON.parse(fs.readFileSync(mapFile)));data.sourceName='MCP4 proteinGroups_030822.txt';data.sourceSHA256=crypto.createHash('sha256').update(bytes).digest('hex');
const read=name=>{let [h,...r]=C.parseDelimited(fs.readFileSync(path.join(root,'Recalculated_data',name),'utf8'),',');return r.map(x=>Object.fromEntries(h.map((k,i)=>[k,x[i]])));};
const rules={'LFQ positive':'lfq','LFQ and same-column MS/MS':'direct','LFQ and same-column MS/MS with global 2 peptides 1 unique':'direct_peptides'};
let counts=0,omissions=0;
for(const x of read('S13_multiculture_counts.csv')){const r=C.analyze(data,{cell:x.cell,category:x.category==='All protein groups'?'all':'gly',rule:rules[x.criterion],minimum:+x.min_cultures,control:x.control_exclusion==='None'?'none':'both'});for(const k of ['SS','PEG','shared','SS_only','PEG_only'])assert.equal(r[k.replace('_','')],+x[k],JSON.stringify(x)+' '+k);counts++;}
for(const x of read('S14_leave_one_culture_out.csv')){const r=C.analyze(data,{cell:x.cell,category:x.category==='All protein groups'?'all':'gly',rule:rules[x.criterion],minimum:1,control:x.control_exclusion==='None'?'none':'both'});const v=r.omissions.find(z=>z.omitSS===x.omitted_SS_experiment&&z.omitPEG===x.omitted_PEG_experiment);for(const k of ['SS','PEG','shared','difference'])assert.equal(v[k],+x[k]);omissions++;}
fs.writeFileSync(output,JSON.stringify(data));console.log(JSON.stringify({source_sha256:data.sourceSHA256,input_rows:data.groups.length,count_scenarios:counts,omission_scenarios:omissions,all_passed:true},null,2));
